/**
 * graphreact-linalg — linear algebra foundation for spectral graph algorithms.
 *
 * Wraps a Rust→WASM binary (built with faer) that provides SVD,
 * eigendecomposition, matrix multiply, linear solve, and row normalization.
 *
 * The WASM glue is generated by wasm-pack (`--target web`). Call the
 * default export to initialise, then use the named exports directly.
 *
 * @example
 * ```ts
 * import init, { svd, eigh, gemm, solve, normalize_rows } from './linalg/index.js';
 *
 * // Initialise once — auto-resolves the .wasm file via import.meta.url:
 * await init();
 *
 * // Then use anywhere:
 * const result = svd(adjacencyMatrix, n, n, k);
 * const { eigenvalues, eigenvectors } = eigh(laplacian, n, k);
 * ```
 */

export {
  default,
  initSync,
  svd,
  eigh,
  gemm,
  solve,
  normalize_rows,
  SvdResult,
  EighResult,
} from './graphreact_linalg.js';

export type { InitInput, InitOutput, SyncInitInput } from './graphreact_linalg.js';
